// 并查集模板
int find(vector<int> &dp, int x) {
    if (x != dp[x]) {
        // 路径压缩
        dp[x] = find(dp, dp[x]);
    }
    return dp[x];
}
// 并查集模板 合并
void merge(int x, int y, vector<int>&dp) {
    int xRoot = find(dp, x);
    int yRoot = find(dp, y);
    int newRoot = min(xRoot, yRoot);
    dp[xRoot] = newRoot;
    dp[yRoot] = newRoot;
}
