package main
​
import (
    "fmt"
    "math"
)
​
// 并查集模板
func find(dp []int, x int) int {
    if x != dp[x] {
        // 路径压缩
        dp[x] = find(dp, dp[x])
    }
    return dp[x]
}
​
// 并查集模板 合并
func merge(x, y int, dp []int) {
    xRoot := find(dp, x)
    yRoot := find(dp, y)
    newRoot := int(math.Min(float64(xRoot), float64(yRoot)))
    dp[xRoot] = newRoot
    dp[yRoot] = newRoot
}
​
func main() {
    var n int
    fmt.Scan(&n)

    // 初始化矩阵
    ans := make([][]int, n)
    for i := 0; i < n; i++ {
        ans[i] = make([]int, n)
    }
​
    // 输入矩阵
    for i := 0; i < n; i++ {
        for j := 0; j < n; j++ {
            fmt.Scan(&ans[i][j])
        }
    }
​
    // 初始化并查集
    dp := make([]int, n+1)
    for i := 1; i <= n; i++ {
        dp[i] = i
    }
​
    // 合并
    for i := 0; i < n; i++ {
        // 矩阵是对称的，只需要遍历左半部分（不包含对角线）
        for j := 0; j < i; j++ {
            if ans[i][j] == 1 {
                merge(i+1, j+1, dp)
            }
        }
    }
​
    // 计算结果
    res := 0
    mp := make(map[int]int)
    for i := 1; i <= n; i++ {
        root := find(dp, i)
        mp[root]++
        if mp[root] > res {
            res = mp[root]
        }
    }
​
    // 输出结果
    fmt.Println(res)
}
